query MyProductListings($limit: Int!, $offset: Int!, $filters: [SellerResourcesFilter]!, $orderBy: SellerResourcesSortOrder!, $sellerId: ID, $resourceIds: [ID!]) {
  seller(sellerId: $sellerId) {
    resources(
      filters: $filters
      orderBy: $orderBy
      paginationParameters: {limit: $limit, offset: $offset}
      resourceIds: $resourceIds
    ) {
      results {
        ...MyResourceFields
        __typename
      }
      pageInfo {
        totalResultsCount
        currentPage
        totalPageCount
        __typename
      }
      __typename
    }
    __typename
  }
}

fragment MyResourceFields on Product {
  id
  name
  canonicalSlug
  kind
  itemType
  statusAdminType {
    id
    __typename
  }
  price
  saleprice
  licenseprice
  discountprice
  isFree
  isFeatured
  images {
    home
    large
    medium
    original
    small
    __typename
  }
  status
  statusAdmin
  statusCopyright
  sold
  evaluationRating {
    scoreAverage
    count
    __typename
  }
  filePreview {
    name
    format
    filesize
    __typename
  }
  resourceProperties {
    assessmentIds
    activityIds
    canConvertToEaselActivity
    isStandaloneEasel
    __typename
  }
  bundle {
    includedItemTypes
    includedOnlineResourceTypes {
      description
      identifier
      __typename
    }
    digitalActivities {
      totalEaselAssessments
      totalEaselActivities
      totalConvertibleEaselActivities
      __typename
    }
    zip {
      status
      __typename
    }
    __typename
  }
  onlineResource {
    onlineResourceType {
      description
      __typename
    }
    __typename
  }
  mainVideo {
    duration
    status
    __typename
  }
  previewVideo {
    id
    __typename
  }
  lastModifiedAt
  postDate
  categories {
    id
    name
    __typename
  }
  taxonomyTags {
    id
    __typename
  }
  author {
    id
    name
    url
    __typename
  }
  __typename
}

